/* Campaign administration follows account access, never a roster role label. */
(()=>{'use strict';
const actor=()=>window.AccountParity?.account?.id||'',ready=()=>{const a=window.AccountParity;return !(a&&(a.connecting||a.busy||a.account&&!a.ready));},hosted=c=>!!(c?.remoteOwnerId||c?.remoteCampaignId||c?.remoteRole||c?.remoteReadOnly),present=c=>!!c&&typeof data!=='undefined'&&data.campaigns.includes(c);
function role(c){if(!present(c)||!ready())return '';if(!hosted(c))return 'owner';const a=window.AccountParity,id=actor();if(!id||!a?.ready)return '';if(c.remoteOwnerId===id||c.remoteRole==='owner')return 'owner';return c.remoteRole||'';}
const canArbitrate=c=>['owner','arbitrator'].includes(role(c)),canEditMatch=c=>['owner','editor','arbitrator'].includes(role(c)),canAssignArbitrator=c=>role(c)==='owner';
const actions=new Set(['edit-campaign','delete-campaign','new-member','new-territory']),cp=new Set(['campaign-image','campaign-image-clear','resource-add','resource-remove','allegiance-add','allegiance-remove','campaign-delete','member-role','member-remove','territory-new','territory-custom-add','territory-preset-add','territory-edit','territory-owner','territory-release','territory-delete','territory-reset-name','pack-edit','pack-save','rich-command','map-editor','map-tool','map-finish','map-object-delete','map-delete']);
const selectors='[data-action],[data-cp],[data-campaign-schedule],[data-ca-module],[data-member-role],[data-member-remove],[data-territory-edit],[data-territory-remove],[data-edit-campaign],[data-delete-campaign]';
function campaignFor(node){const id=node?.dataset?.campaignId||node?.dataset?.editCampaign||node?.dataset?.deleteCampaign||(['edit-campaign','delete-campaign'].includes(node?.dataset?.action)?node.dataset.id||node.dataset.value:'');return id?data.campaigns.find(c=>c.id===id):typeof campaign==='function'&&data.view==='campaign'?campaign():null;}
function administrative(node){const d=node.dataset;if(actions.has(d.action)||cp.has(d.cp)||node.matches('[data-member-role],[data-member-remove],[data-territory-edit],[data-territory-remove],[data-edit-campaign],[data-delete-campaign]'))return true;if(['configure','advance','undo'].includes(d.campaignSchedule))return true;if(d.caModule==='core'&&['deadlines','announce'].includes(d.caAction))return true;return d.caModule==='challenges'&&['open-cycle','review-cycle'].includes(d.caAction);}
const disabled=new Map();let queued=false;
function refresh(){queued=false;for(const [node,old]of disabled){if(node.isConnected){if('disabled'in node)node.disabled=old.disabled;if(old.aria==null)node.removeAttribute('aria-disabled');else node.setAttribute('aria-disabled',old.aria);node.removeAttribute('data-arbitrator-disabled');}}disabled.clear();for(const node of document.querySelectorAll(selectors)){if(!administrative(node))continue;const c=campaignFor(node);if(!c||canArbitrate(c))continue;disabled.set(node,{disabled:!!node.disabled,aria:node.getAttribute('aria-disabled')});if('disabled'in node)node.disabled=true;node.setAttribute('aria-disabled','true');node.dataset.arbitratorDisabled='';}}
function schedule(){if(queued)return;queued=true;queueMicrotask(refresh);}
window.addEventListener('click',event=>{const node=event.target.closest?.(selectors);if(node&&administrative(node)){const c=campaignFor(node);if(c&&!canArbitrate(c)){event.preventDefault();event.stopImmediatePropagation();}}},true);
new MutationObserver(schedule).observe(document.body,{childList:true,subtree:true});window.addEventListener('uk:languagechange',schedule);
window.MMCampaignPermissions={role,canArbitrate,canEditMatch,canAssignArbitrator,refresh:schedule};schedule();
})();
